// The sheet write above is the only thing stopping a lead being emailed twice.
// If it quietly wrote nothing, stop the entire run here rather than mail the
// remaining leads with no way to record them.
const written = $json ?? {};
const lead = $('Compose email').first().json;

if (Object.keys(written).length === 0 || !String(written['Status'] ?? '').trim()) {
  throw new Error(
    `Row ${lead.row_number} (${lead.Business}) was EMAILED but NOT marked in the sheet, ` +
    `so it would be emailed again on the next run. The update returned nothing, which ` +
    `means the tab has no "Status" / "Sent at" / "Send error" columns, or they are ` +
    `spelled differently. Add them to the tab (exact spelling, row 1), then run again. ` +
    `Stopping now so only this one lead is affected.`
  );
}

// Carry the lead itself back into the loop, so Run summary sees real rows
// instead of whatever the Sheets API happened to return.
return { json: { ...lead, Status: written['Status'], 'Sent at': written['Sent at'] } };
